// Часовой пояс журнала: по умолчанию UTC. При необходимости задайте своё смещение в минутах.
const REPORT_UTC_OFFSET_MINUTES = 0;
if (!$('Только владелец').isExecuted) return [];
const m = $('Telegram: рабочий вход').first().json.message;
const a = $input.first().json.output ?? {};
const norm = s => String(s).normalize('NFKC').replace(/\s+/g,' ').trim();
const quote = s => typeof s === 'string' && s.trim() && m.text.includes(s.trim()) ? norm(s) : '';
const received = new Date(m.date * 1000 + REPORT_UTC_OFFSET_MINUTES * 60000).toISOString().slice(0,10);
function dateOf(s) {
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const word = s.toLowerCase().match(/^(\d{1,2}) ([а-яё]+)(?: (\d{4})(?: г\.?)?)?$/u);
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const dot = s.match(/^(\d{1,2})\.(\d{1,2})(?:\.(\d{4}))?$/);
  const [y,mo,d] = word ? [word[3], months.indexOf(word[2])+1, word[1]] : iso ? iso.slice(1) : dot ? [dot[3],dot[2],dot[1]] : [];
  if (!Number(mo) || !Number(d)) return '';
  const year = y ?? received.slice(0,4);
  const stamp = year + '-' + String(mo).padStart(2,'0') + '-' + String(d).padStart(2,'0');
  const dt = new Date(stamp + 'T00:00:00Z');
  return Number(year) >= 1900 && Number.isFinite(+dt) && dt.toISOString().slice(0,10) === stamp && stamp <= received ? stamp : '';
}
function rub(s) {
  const m = s.match(/^(\d{1,3}(?: \d{3})+|\d+)([,.]\d{1,2})? *(млн\.?|миллион(?:а|ов)?|тыс\.?|тысяч(?:а|и)?)? *(руб(?:лей|ля|ль)?\.?|₽|RUB)$/iu);
  if (!m) return '';
  const value = Math.round(Number(m[1].replace(/ /g,'') + (m[2] || '').replace(',','.')) * (/^м/iu.test(m[3] || '') ? 1e6 : /^т/iu.test(m[3] || '') ? 1000 : 1) * 100) / 100;
  return value > 0 && value <= 1e10 ? value : '';
}
const date = dateOf(quote(a.dateQuote));
const model = quote(a.car);
const amount = rub(quote(a.priceQuote));
let kind = a.kind === 'Продажа' || a.kind === 'Заявка' ? a.kind : 'На проверке';
let note = kind === 'На проверке' && typeof a.reason === 'string' ? a.reason.trim().slice(0,300) : '';
if (!date || !model || amount === '') {
  kind = 'На проверке';
  if (!note) note = [!date && 'Не подтверждена дата события', !model && 'Не подтверждена модель автомобиля', amount === '' && 'Не подтверждена сумма в рублях'].filter(Boolean).join('; ');
}
if (kind === 'На проверке' && !note) note = 'Не подтверждён тип события.';
return [{json:{id:'tg:'+m.chat.id+':'+m.message_id,date,month:date.slice(0,7),kind,model,amount,link:'',original:m.text,note,reply:m.reply_to_message?.message_id ?? null}}];

const values = $input.first().json.values;
if (!Array.isArray(values) || !["ID сообщения","Дата события","Месяц отчёта","Тип","Автомобиль","Сумма, ₽","ID заявки (если связан)","Исходный текст","Причина проверки"].every((label,i) => values[0]?.[i] === label)) throw new Error('Проверьте шапку листа SalesLog.');
const p = $('Проверить реквизиты').first().json;
const rows = values.slice(1);
if (rows.some(r => r[0] === p.id)) return [];
if (p.reply && p.kind === 'Продажа') {
  const parent = p.id.replace(/:\d+$/, ':' + p.reply);
  const found = rows.filter(r => r[0] === parent && r[3] === 'Заявка');
  const normalize = s => String(s).normalize('NFKC').replace(/\s+/g,' ').trim().toLowerCase();
  if (found.length === 1 && normalize(found[0][4]) === normalize(p.model) && /^\d{4}-\d{2}-\d{2}$/.test(found[0][1]) && found[0][1] <= p.date && !rows.some(r => r[3] === 'Продажа' && r[6] === parent)) p.link = parent;
  else { p.kind = 'На проверке'; p.note = 'Ответ на сообщение: связь с заявкой не подтверждена. Проверьте вручную.'; }
}
return [{json:{values:[[p.id,p.date,p.month,p.kind,p.model,p.amount,p.link,p.original,p.note]]}}];

const OWNER_ID = ''; // Укажите разрешённый Telegram ID в приватной копии.
const m = $input.first().json.message;
if (!/^[1-9]\d+$/.test(OWNER_ID) || m?.chat?.type !== 'private' || String(m.from?.id) !== OWNER_ID || String(m.chat.id) !== OWNER_ID || m.from.is_bot !== false) return [];
if (typeof m.text !== 'string' || !m.text.trim() || m.text.trimStart().startsWith('/') || !Number.isSafeInteger(m.date) || m.date <= 0 || m.date > 4102444800 || !Number.isSafeInteger(m.message_id) || m.message_id <= 0) return [];
return [{json:{text:m.text}}];
